# Maps are thematic/scope relations, not equivalences and not new Lean coverage claims.
def mapping(i):
 if i<=2:return [1], 'extension' if i==2 else 'analogue'
 if i in [3,4,5]:return [2,3], 'generalization' if i!=5 else 'additional consequence'
 if i==6:return [4],'generalization'
 if 7<=i<=10:return [5],'generalization or consequence'
 if 11<=i<=17:return [6],'analogue' if i==11 else 'additional stability development'
 if i==18:return [7],'analogue'
 if i==19:return [8],'analogue'
 if 20<=i<=22:return [9,13],'Hilbert-space development'
 if i==23:return [15],'analogue; latest source adds total tie rule and complexity bound'
 if i in[24,25]:return [14,16],'additive special case; latest source includes nonadditive finite selection'
 if i in[26,27]:return [10,11],'additional analytic decomposition; not represented by the 20-result scope'
 if i in[28,29]:return [10,11],'analogue / conditional approximation consequence'
 if 30<=i<=36:return [12],'additional quantitative development'
 if 37<=i<=45:return [10,11,12],'additional recovery development; not a Lean coverage claim'
 if 46<=i<=53:return [],'additional localization development outside the 20-result scope'
 if 54<=i<=56:return [10,11,12],'consequence / quantitative extension'
 if i==57:return [17],'analogue'
 if i in[58,59]:return [17],'additional nonlinear sample-coordinate law'
 if i==60:return [18],'analogue'
 if i==61:return [19],'analogue'
 if i==62:return [18,20],'secondary coordinate consequence'
 if i==63:return [20],'coprime group-label generalization'
pat=re.compile(r'\\begin\{(theorem|lemma|proposition|corollary)\}(?:\[([^\]]*)\])?\\label\{([^}]+)\}')
rows=[]
for i,m in enumerate(pat.finditer(s),1):
 env,title,label=m.groups();end=s.index('\\end{'+env+'}',m.end())+len('\\end{'+env+'}')
 p0=s.index('\\begin{proof}',end);p1=s.index('\\end{proof}',p0)+len('\\end{proof}')
 targets,relation=mapping(i)
 rows.append({'index':i,'environment':env,'title':title,'label':label,'line':s.count('\n',0,m.start())+1,'statement_sha256':hashlib.sha256(s[m.start():end].encode()).hexdigest(),'proof_sha256':hashlib.sha256(s[p0:p1].encode()).hexdigest(),'latest20_related_results':targets,'relation':relation,'lean_coverage':'not established by this thematic map','raw_proof_read':True,'repair_or_clarification_ids':fix_by_loc.get(label,[]),'obligation_status':'requires listed repair/clarification' if label in fix_by_loc else 'local derivation passed subject to stated domain and standard background leaves'})
assert len(rows)==63
report={'schema':'komorebi.paper_v.annals_review.v1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer_task':'/root/paper5_audit/annals_scope','primary_verdict':'correct only after a stated restriction','normalized_claim':'The 63 historical Annals proof developments may be retained as a separate prose development after the listed domain repairs; they are not 63 additionally Lean-checked manuscript results.','source_pins':[{'path':str(SRC),'sha256':sha(SRC)},{'path':str(LATEST),'sha256':sha(LATEST)}],'scope':{'raw_theorem_proofs_read':63,'latest_scope':'20 result groups, thematic crosswalk only in this branch','computational_checks':'No fresh numerical suite or Lean compilation performed in this branch. Counterexamples and critical constants reconstructed analytically.','external_sources':'No fresh primary-source authentication in this branch. Parent informed of unresolved external leaves.','not_claimed':['complete kernel verification','new global novelty','83 independent results from 20 + 63','all historical audit claims authenticated']},'repairs':fixes,'dependency_graph':[['lattice cosets','polyphase isometry','convolution transfer','bank Fourier multiplier','packet trees'],['Sobolev trace cancellation','global Sobolev remainder','retained packet identity','conditional approximation rate'],['exact indicator overlaps','packet norm error','linear estimated-packet identity','reconstruction error'],['Lipschitz increment and noise','contrast gap','exact jump-cell recovery','packet error','probability consistency'],['smooth Haar estimate','step Haar coefficient','scale gap','half-grid distance','alignment-free presence detection'],['finite polynomial difference','binomial noise norm','breakpoint response bands'],['finite additive objective','tree recursion','uniform cost perturbation','gap stability'],['Cayley conjugacy','cyclic action','coprime label CRT']], 'external_or_background_leaves':[{'leaf':'Young inequality and Plancherel','status':'conditional external background not reauthenticated','used_by':'transfer and filter-bank sections'},{'leaf':'finite-dimensional multiplier essential-sup norm and singular-value facts','status':'standard background derivation locally reconstructed; no source authentication','used_by':'sharp multiplier norm and canonical dual estimates'},{'leaf':'one-dimensional Sobolev representatives and traces','status':'conditional standard background; gluing step reconstructed by integration by parts','used_by':'higher order trace packet decomposition'},{'leaf':'Minkowski integral inequality','status':'standard background not reauthenticated','used_by':'higher-order location Lipschitz constant'},{'leaf':'sub-Gaussian Chernoff bound','status':'locally reconstructed from stated moment-generating-function inequality and independence','used_by':'probability recovery'},{'leaf':'classical Gibbs asymptotics','status':'conditional external fact; regularity restriction required','used_by':'context only; no theorem proof depends on it'},{'leaf':'Chinese remainder theorem','status':'standard finite group fact not freshly source-authenticated','used_by':'coprime phase factorization'}], 'critical_derivations':{'higher_order_trace':'For ell<m, truncated-power ell derivative is continuous at tau; for ell=m it has unit jump; for ell>m its side derivatives vanish. Packet derivative-jump matrix is diagonal in (m,tau). Subtracting coefficients cancels every trace through r - 1; piecewise integration by parts cancels interface terms, giving global W^{r,p}.','higher_order_location':'Integral in location of phi_{m-1,u}; its Lp norm on (0,1) is <=1/((m-1)!((m-1)p+1)^(1/p)), so Minkowski gives the displayed Lipschitz constant.','geometry':'Region intersections partition the domain exactly. Equal-amplitude error is |a|mu(E triangle F)^(1/p). A local tube estimate can only be applied inside its radius range.','deterministic':'D_k=a_q+(s(t_{k+1})-s(t_k))+(eta_{k+1}-eta_k) on a one-jump cell. Residual<=Mh+2eps. Strict threshold interval exists iff a_min>2b. Midpoint error<=h/2 and disjoint detected cells let the location Lp errors add in pth powers.','probability':'Independent sigma-subGaussian differences have mgf<=exp(sigma^2lambda^2). Chernoff gives two-tail<=2exp(-t^2/(4sigma^2)); n-cell union bound with t =2sigma sqrt(log(2n/delta)) gives delta. Adjacent contrasts need not be independent for the union bound. Sigma=0 is handled as deterministic zero noise, avoiding division by zero.','haar':'Smooth coefficient<=ML^(3/2)/4 by pairing half-cell points. Half-line step coefficient=|a|sqrtL min(u,1-u). Bounded noise coefficient<=eps sqrtL. Compare upper and lower for threshold. Modulo L, either grid places tau at distance >= L/4 from endpoints.','best_basis':'Finite prunings give an attained minimum; each subtree pruning stops or splits. Uniform pruning-cost perturbation<= epsilon_star implies optimum difference<= epsilon_star. Strict competitor gaps remain positive if 2 epsilon_star < g. Ties/singletons need explicit total selection conventions.','difference':'Binomial coefficients have sum of absolute values 2^m; (d + 1)st difference vanishes on a degree<=d polynomial stencil. The breakpoint-band theorem requires a nonzero response assumption and does not prove every breakpoint has one.'},'inventory':rows,'recommendation':'Retain the latest 20-result edition as the formal coverage spine and the corrected Annals 63-proof body as a separately labeled analytic development. Preserve source snapshots unchanged and log exact corrections in the final edition. Keep all 63 proof bodies, updating only local hypotheses/conventions and their necessary short proof sentences. Do not sum 20 + 63 as 83 nonoverlapping or Lean-verified results.'}
out=ROOT/'audit/annals_review.json';out.write_text(json.dumps(report,indent=2)+'\n')
lines=['PAPER V: HISTORICAL ANNALS PROOF REVIEW','', 'Primary verdict: correct only after a stated restriction.',report['normalized_claim'],'','SOURCE PINS']
