for e in report['external_or_background_leaves']:lines +=[e['leaf']+' | '+e['status']+' | '+e['used_by']]
lines+=['','63-RESULT INVENTORY AND THEMATIC LATEST 20 CROSSWALK','Each row is a historical result record, not a distinct new Lean result. Statement/proof hashes are in the JSON.']
for row in rows:lines +=[f"{row['index']:02d} | line {row['line']} | {row['label']} | latest {row['latest20_related_results']} | {row['relation']} | fixes {row['repair_or_clarification_ids']}"]
lines+=['','RETENTION RECOMMENDATION',report['recommendation'],'','LIMITS','No fresh external theorem authentication, Lean build, full formal semantic audit, or numerical-suite execution occurred in this branch. The corrected final manuscript must be checked against these recommendations and pinned separately before its new revision receives a verdict.']
